/// The element a root is: its namespaces, preferred prefix and local name.
pub(crate) fn root_name(r: &m::Root) -> (&'static [&'static str], &'static str, &'static str) {
    match r {
        m::Root::ColorsDef(_) => (NS_DGM, "dgm", "colorsDef"),
        m::Root::ColorsDefHdr(_) => (NS_DGM, "dgm", "colorsDefHdr"),
        m::Root::ColorsDefHdrLst(_) => (NS_DGM, "dgm", "colorsDefHdrLst"),
        m::Root::DataModel(_) => (NS_DGM, "dgm", "dataModel"),
        m::Root::LayoutDef(_) => (NS_DGM, "dgm", "layoutDef"),
        m::Root::LayoutDefHdr(_) => (NS_DGM, "dgm", "layoutDefHdr"),
        m::Root::LayoutDefHdrLst(_) => (NS_DGM, "dgm", "layoutDefHdrLst"),
        m::Root::RelIds(_) => (NS_DGM, "dgm", "relIds"),
        m::Root::StyleDef(_) => (NS_DGM, "dgm", "styleDef"),
        m::Root::StyleDefHdr(_) => (NS_DGM, "dgm", "styleDefHdr"),
        m::Root::StyleDefHdrLst(_) => (NS_DGM, "dgm", "styleDefHdrLst"),
        m::Root::DspDrawing(_) => (NS_DSP, "dsp", "drawing"),
        m::Root::DspDataModelExt(_) => (NS_DSP, "dsp", "dataModelExt"),
        m::Root::Dgm14CNvPr(_) => (NS_DGM14, "dgm14", "cNvPr"),
        m::Root::Dgm14RecolorImg(_) => (NS_DGM14, "dgm14", "recolorImg"),
        m::Root::Dgm1611AutoBuNodeInfoLst(_) => (NS_DGM1611, "dgm1611", "autoBuNodeInfoLst"),
        m::Root::Dgm1612SpPr(_) => (NS_DGM1612, "dgm1612", "spPr"),
        m::Root::Dgm1612LstStyle(_) => (NS_DGM1612, "dgm1612", "lstStyle"),
    }
}
